const item = $input.all()[0];
const json = item.json;
let phase = 'REQUIREMENTS';
if (json.body && typeof json.body === 'object' && json.body.phase) {
  phase = String(json.body.phase).trim().toUpperCase();
} else if (json.phase) {
  phase = String(json.phase).trim().toUpperCase();
}
return [{ json: { ...json, _phase: phase } }];

const { Client } = require('pg');
const functionUnitId = parseInt(query, 10);
if (isNaN(functionUnitId)) return '错误：输入参数必须是功能单元ID（纯数字），例如 7。请重新调用此工具并传入正确的功能单元ID。';

const client = new Client({
  host: 'postgres',
  port: 5432,
  database: 'workflow_platform_dev',
  user: 'platform_dev',
  password: 'dev_password_123'
});

try {
  await client.connect();
  const result = {};

  // 1. 功能单元基本信息
  const fuRes = await client.query('SELECT id, name, description, created_at, updated_at FROM dw_function_units WHERE id = $1', [functionUnitId]);
  result.functionUnit = fuRes.rows[0] || null;

  // 2. 已有AI文档（需求文档、设计文档）
  const docsRes = await client.query('SELECT document_type, version, content, summary, created_at FROM dw_ai_documents WHERE function_unit_id = $1 ORDER BY document_type, version DESC', [functionUnitId]);
  result.documents = docsRes.rows;

  // 3. 表定义
  const tablesRes = await client.query('SELECT id, table_name, table_display_name, table_type, description FROM dw_table_definitions WHERE function_unit_id = $1 ORDER BY id', [functionUnitId]);
  result.tableDefinitions = tablesRes.rows;

  // 4. 字段定义（关联表定义）
  if (tablesRes.rows.length > 0) {
    const tableIds = tablesRes.rows.map(t => t.id);
    const fieldsRes = await client.query('SELECT table_id, field_name, data_type, length, nullable, is_primary_key, description, sort_order FROM dw_field_definitions WHERE table_id = ANY($1) ORDER BY table_id, sort_order', [tableIds]);
    result.fieldDefinitions = fieldsRes.rows;
  } else {
    result.fieldDefinitions = [];
  }

  // 5. 表单定义
  const formsRes = await client.query('SELECT id, form_name, form_type, description FROM dw_form_definitions WHERE function_unit_id = $1', [functionUnitId]);
  result.formDefinitions = formsRes.rows;

  // 6. 动作定义
  const actionsRes = await client.query('SELECT action_name, action_type, description, is_default FROM dw_action_definitions WHERE function_unit_id = $1', [functionUnitId]);
  result.actionDefinitions = actionsRes.rows;

  // 7. 外键
  if (tablesRes.rows.length > 0) {
    const tableIds = tablesRes.rows.map(t => t.id);
    const fkRes = await client.query('SELECT fk.id, fd.field_name, rt.table_name as ref_table_name, rf.field_name as ref_field_name, fk.on_delete, fk.on_update FROM dw_foreign_keys fk LEFT JOIN dw_field_definitions fd ON fk.field_id = fd.id LEFT JOIN dw_table_definitions rt ON fk.ref_table_id = rt.id LEFT JOIN dw_field_definitions rf ON fk.ref_field_id = rf.id WHERE fk.table_id = ANY($1)', [tableIds]);
    result.foreignKeys = fkRes.rows;
  } else {
    result.foreignKeys = [];
  }

  await client.end();

  // 格式化输出
  let output = '';
  if (result.functionUnit) {
    output += `【功能单元】${result.functionUnit.name} (ID: ${result.functionUnit.id})\n`;
    output += `描述: ${result.functionUnit.description || '无'}\n\n`;
  } else {
    output += `【功能单元】这是一个全新的功能单元 (ID: ${functionUnitId})，尚未创建组件数据。请正常帮助用户进行需求分析和设计。\n\n`;
  }

  if (result.documents.length > 0) {
    output += `【已有文档】共 ${result.documents.length} 份\n`;
    const seen = new Set();
    for (const doc of result.documents) {
      if (seen.has(doc.document_type)) continue;
      seen.add(doc.document_type);
      output += `\n--- ${doc.document_type} 文档 (版本 ${doc.version}) ---\n`;
      output += doc.content + '\n';
    }
    output += '\n';
  } else {
    output += '【已有文档】无\n\n';
  }

  if (result.tableDefinitions.length > 0) {
    output += `【表定义】共 ${result.tableDefinitions.length} 张表\n`;
    for (const t of result.tableDefinitions) {
      output += `- ${t.table_name} (${t.table_display_name || ''}, 类型: ${t.table_type})\n`;
      const fields = result.fieldDefinitions.filter(f => f.table_id === t.id);
      for (const f of fields) {
        output += `  · ${f.field_name} ${f.data_type}${f.length ? '(' + f.length + ')' : ''} ${f.nullable ? 'NULL' : 'NOT NULL'}${f.is_primary_key ? ' PK' : ''} ${f.description || ''}\n`;
      }
    }
    output += '\n';
  } else {
    output += '【表定义】无\n\n';
  }

  if (result.foreignKeys.length > 0) {
    output += `【外键】共 ${result.foreignKeys.length} 个\n`;
    for (const fk of result.foreignKeys) {
      output += `- ${fk.field_name} -> ${fk.ref_table_name}.${fk.ref_field_name}\n`;
    }
    output += '\n';
  }

  if (result.formDefinitions.length > 0) {
    output += `【表单定义】共 ${result.formDefinitions.length} 个\n`;
    for (const f of result.formDefinitions) {
      output += `- ${f.form_name} (类型: ${f.form_type})\n`;
    }
    output += '\n';
  }

  if (result.actionDefinitions.length > 0) {
    output += `【动作定义】共 ${result.actionDefinitions.length} 个\n`;
    for (const a of result.actionDefinitions) {
      output += `- ${a.action_name} (类型: ${a.action_type}, 默认: ${a.is_default})\n`;
    }
  }

  return output;
} catch (err) {
  try { await client.end(); } catch(e) {}
  return '数据库查询失败: ' + err.message;
}

