const agentOutput = $input.first().json;
const reply = agentOutput.output || agentOutput.text || '';

let document = null;
let documentType = null;
let phaseComplete = false;
let generatedData = null;

// Detect document content in reply
const reqDocMatch = reply.match(/---REQUIREMENTS_DOC_START---([\s\S]*?)---REQUIREMENTS_DOC_END---/);
const designDocMatch = reply.match(/---DESIGN_DOC_START---([\s\S]*?)---DESIGN_DOC_END---/);
const genDataMatch = reply.match(/---GENERATED_DATA_START---([\s\S]*?)---GENERATED_DATA_END---/);

if (reqDocMatch) {
  document = reqDocMatch[1].trim();
  documentType = 'REQUIREMENTS';
}
if (designDocMatch) {
  document = designDocMatch[1].trim();
  documentType = 'DESIGN';
}

// Detect phase completion signal
if (reply.includes('---PHASE_COMPLETE---')) {
  phaseComplete = true;
}

// Extract generated data JSON
if (genDataMatch) {
  try {
    generatedData = JSON.parse(genDataMatch[1].trim());
  } catch (e) {
    // Try to extract JSON from code block
    const jsonBlock = genDataMatch[1].match(/```json?\s*([\s\S]*?)```/);
    if (jsonBlock) {
      try {
        generatedData = JSON.parse(jsonBlock[1].trim());
      } catch (e2) {
        // Leave as null, backend will handle
      }
    }
  }
}

// Clean reply text by removing markers
let cleanReply = reply
  .replace(/---REQUIREMENTS_DOC_START---[\s\S]*?---REQUIREMENTS_DOC_END---/g, '')
  .replace(/---DESIGN_DOC_START---[\s\S]*?---DESIGN_DOC_END---/g, '')
  .replace(/---GENERATED_DATA_START---[\s\S]*?---GENERATED_DATA_END---/g, '')
  .replace(/---PHASE_COMPLETE---/g, '')
  .trim();

return [{
  json: {
    reply: cleanReply,
    document: document,
    documentType: documentType,
    phaseComplete: phaseComplete,
    generatedData: generatedData
  }
}];
